-- Library Keeper catalog snapshot (generated by scripts/catalog_snapshot.py export)
BEGIN;
CREATE TABLE books (
            book_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            author TEXT NOT NULL,
            publisher TEXT,
            publication_year INTEGER,
            page_count INTEGER,
            isbn TEXT,
            cover_url TEXT,
            language TEXT DEFAULT 'ar',
            genre TEXT,
            price REAL DEFAULT 0.0,
            quantity INTEGER DEFAULT 0,
            shelf_location TEXT,
            active INTEGER DEFAULT 1
        , barcode TEXT, rewaa_sku TEXT, source TEXT, last_synced_at TEXT, original_language TEXT, translator TEXT);
CREATE TABLE book_profiles (
            profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
            book_id INTEGER NOT NULL UNIQUE,
            language_difficulty TEXT,
            pace TEXT,
            perceived_length TEXT,
            ending_tone TEXT,
            reader_level TEXT,
            age_suitability TEXT,
            moods TEXT,
            themes TEXT,
            sensitive_content TEXT,
            use_cases TEXT,
            overall_status TEXT,
            last_enriched_at TEXT, format TEXT, genres TEXT, emotional_weight TEXT,
            FOREIGN KEY (book_id) REFERENCES books(book_id) ON DELETE CASCADE
        );
CREATE TABLE attribute_evidence (
            evidence_id INTEGER PRIMARY KEY AUTOINCREMENT,
            book_id INTEGER NOT NULL,
            attribute_name TEXT NOT NULL,
            attribute_value TEXT NOT NULL,
            confidence REAL NOT NULL DEFAULT 0.0,
            evidence_summary TEXT,
            source_urls TEXT,
            source_site TEXT,
            edition_scope TEXT,
            review_count INTEGER DEFAULT 0,
            conflict_seen INTEGER DEFAULT 0,
            analyzed_at TEXT,
            human_verified INTEGER DEFAULT 0,
            verified_by TEXT,
            verified_at TEXT, rejected INTEGER DEFAULT 0, rejected_at TEXT, rejected_by TEXT,
            FOREIGN KEY (book_id) REFERENCES books(book_id) ON DELETE CASCADE
        );
CREATE INDEX idx_books_barcode ON books(barcode);
CREATE INDEX idx_books_rewaa_sku ON books(rewaa_sku);
COMMIT;
